// the row whose name is `name`, ignoring case and spaces (a spirit's entity name may run its words together) ;
// -1 for a name that is no avatar
inline int smn_avatar_index(const char* name) {
    if (!name || !name[0]) return -1;
    for (int i = 0; i < SMN_AVATARS_N; ++i) {
        const char* a = SMN_AVATARS[i].en; const char* b = name;
        for (;;) {
            while (*a == ' ') ++a;
            while (*b == ' ') ++b;
            const char ca = (*a >= 'A' && *a <= 'Z') ? (char)(*a + 32) : *a, cb = (*b >= 'A' && *b <= 'Z') ? (char)(*b + 32) : *b;
            if (ca != cb) break;
            if (!ca) return i;
            ++a; ++b;
        }
    }
    return -1;
}

